2>&1 | head -2; done; echo '---write multi-log verdict---'; python -c "
import json, os
root = '$OUT_ROOT'
uuids = '$UUIDS'.split()
result = {'uuids': uuids, 'per_log': {}}
for u in uuids:
    d = os.path.join(root, u)
    if not os.path.isdir(d):
        result['per_log'][u] = {'status': 'missing'}
        continue
    info = {'status': 'ok'}
    for key, fname in (('lidar', 'lidar_aggregate.json'), ('cycle', 'cycle_aggregate.json')):
        p = os.path.join(d, fname)
        if os.path.exists(p):
            try:
                info[key] = json.load(open(p))
            except Exception as e:
                info[key+'_error'] = str(e)
        else:
            info[key] = None
    result['per_log'][u] = info
open(os.path.join(root, 't1_multilog_done.json'),'w').write(json.dumps(result, indent=2, default=str))
print('wrote verdict')
" 2>&1 | tail -5; echo "[t1-multilog] done $(date -u)"; ls -la "$OUT_ROOT"
